@startuml

class Employee {
  + name : string
  + ssn : int
}

class CreativeEmployee extends Employee {
  + hasOscar : boolean
}

class Director extends CreativeEmployee {
  + assistantName : string
}

class Actor extends CreativeEmployee {
  + education : string
}

class Technician extends Employee {
  + fieldOfActivity : string
}

class Location {
  + name : string
}

class Film {
  + title : string
  + releaseYear : int
}

class Genre {
  Thriller
  Action
  Horror
  Comedy
}

class Screenwriter {
  + name : string
  + mostSuccessfulFilm : string
}

class Screenplay {
  + title : string
  + version : string
  + date : date
  + numberOfScenes : int
  + plot : string
}

class Novel {
  + title : string
}

class Author {
  + name : string
}

class Concept {}

Film "*" -- "*" Location : used at
Film "*" -- "1" Genre : belongs to
Film "1" -- "1" Screenplay : based on
Film "1" -- "1" Director : directed by
Film "1" -- "*" Actor : features

Screenwriter "1" -- "*" Screenplay : creates
Screenplay "1" -- "0..1" Novel : based on
Screenplay "1" -- "0..1" Concept : based on
Novel "*" -- "1" Author : written by

Actor "*" -- "1" Screenplay : reads for role

@enduml

